import java.util.ArrayList;
import java.util.HashMap;
import java.util.concurrent.ThreadLocalRandom;

class RandomizedSet {
    private final ArrayList<Integer> values = new ArrayList<>();
    private final HashMap<Integer, Integer> indices = new HashMap<>();

    public RandomizedSet() {
    }

    public boolean insert(int val) {
        if (indices.containsKey(val)) return false;
        indices.put(val, values.size());
        values.add(val);
        return true;
    }

    public boolean remove(int val) {
        Integer index = indices.get(val);
        if (index == null) return false;
        int lastIndex = values.size() - 1;
        int lastValue = values.get(lastIndex);
        values.set(index, lastValue);
        indices.put(lastValue, index);
        values.remove(lastIndex);
        indices.remove(val);
        return true;
    }

    public int getRandom() {
        return values.get(ThreadLocalRandom.current().nextInt(values.size()));
    }
}
